<script>import Modal from '../../../components/Modal.svelte';let {item,onClose,onSave,busy=false}= $props();let title=$state(item?.title||'');let type=$state(item?.type||'public');let description=$state(item?.description||'');let error=$state('');async function submit(e){e.preventDefault();if(!title.trim()){error='Judul wajib diisi.';return;}try{await onSave({title:title.trim(),type,description:description.trim()});}catch(err){error=err.message||'Gagal menyimpan perubahan.';}}</script>
<Modal title="Ubah Link Tree" {onClose}><form onsubmit={submit} class="form-stack"><label for="change-title">Nama link tree</label><input id="change-title" bind:value={title} required maxlength="100"/><label for="change-type">Privasi</label><select id="change-type" bind:value={type}><option value="public">Public</option><option value="unlisted">Unlisted</option><option value="private">Private</option></select><label for="change-description">Deskripsi</label><textarea id="change-description" bind:value={description} rows="3" maxlength="500"></textarea>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="btn btn-light" onclick={onClose}>Batal</button><button class="btn btn-primary" disabled={busy}>{busy?'Menyimpan…':'Simpan perubahan'}</button></div></form></Modal>
